import { DirtyLevels } from "./constants"

export let activeEffect

export class ReactiveEffect {

    _trackId = 0 //记录当前effect执行了几次
    _dirty = DirtyLevels.Dirty
    _depslength = 0
    _running = false
    _deps = []
    public active = true
    private _parent: ReactiveEffect | undefined
    constructor(public fn, public scheduler) {

    }

    // 观察当前effect是否为脏值
    public get dirty() {
        return this._dirty === DirtyLevels.Dirty
    }

    // 修改脏值
    public set dirty(v) {
        this._dirty = v ? DirtyLevels.Dirty : DirtyLevels.NoDirty
    }

    run() {
        this._dirty = DirtyLevels.NoDirty
        // 让fn执行
        if (!this.active) return this.fn()
        // 
        if (this._running) return
        this._running = true
        this._parent = activeEffect
        // let lastEffect = activeEffect
        try {
            activeEffect = this
            // 初始化依赖长度和依赖版本更新
            preCleanEffect(this)
            return this.fn()
        } finally {
            // 删除多余的旧依赖
            postCleanEffect(this)
            this._running = false
            // activeEffect = lastEffect
            activeEffect = this._parent
        }
    }
    stop() {
        if (this.active) {
            this.active = false
            preCleanEffect(this)
            postCleanEffect(this)
        }
    }
}

export function effect(fn, options?) {
    // 创建一个响应式effect 数据变化后可以重新执行
    const _effect = new ReactiveEffect(fn, () => _effect.run())
    _effect.run()
    if (options) {
        Object.assign(_effect, options)
    }

    const runner = _effect.run.bind(_effect)
    runner.effect = _effect // 可以在run方法中获取_effect
    return runner
}

function preCleanEffect(e) {
    e._depslength = 0
    e._trackId++
}

function postCleanEffect(e) {
    if (e._deps.length > e._depslength) {
        for (let i = e._depslength; i < e._deps.length; i++) {
            clearDepEffect(e._deps[i], e)
        }
        // 清理后要截断数组，否则下次复用会有残留
        e._deps.length = e._depslength
    }
}

// 删除旧依赖，是为了提高一点性能。并不是必须要的，源码里面没有这个逻辑
function clearDepEffect(dep, effect) {
    dep.delete(effect)
    if (dep.size == 0) dep.cleanup()
}

// 双向依赖收集
export function trackEffect(effect, dep) {
    if (dep.get(effect) !== effect._trackId) {
        dep.set(effect, effect._trackId)
        let oldDep = effect._deps[effect._depslength]
        // console.log(oldDep);
        // 判断旧依赖和新依赖是否相同，不一样让新依赖覆盖旧依赖
        if (oldDep !== dep) {
            if (oldDep) clearDepEffect(oldDep, effect)
            effect._deps[effect._depslength++] = dep
            /* 
            *这行代码是为了处理effect临时嵌套,导致持续持续创建新的ReactiveEffect实例应用地址,导致多次调用内层的临时effect()函数
            *该代码目前有有bug存在,需要进一步优化 
            *局限1: 无法区分持久内层和临时内层
            *局限2: 幽灵引用问题。
            *为了下面的学习最好把下面代码注释掉
            *后果:造成effect内部创建的临时effect会一直创建新的reactiveEffect引用地址导致响应式对象中的_dep旧的依赖地址无法删除,响应式对象中的_dep会一直增长
            */
            // if (dep.size > 1 && effect._parent) dep.delete(effect)
        } else {
            effect._depslength++
        }
    }
}

// 触发依赖重新执行effect.run()
export function triggerEffects(dep) {
    for (const effect of dep.keys()) {
        if (effect._dirty < DirtyLevels.Dirty) {
            effect._dirty = DirtyLevels.Dirty
        }
        if (effect.scheduler && !effect._running) {
            effect.scheduler()
        }
    }
}


